//! Data component types registered by plugins on top of the vanilla ones.
//!
//! # Design
//!
//! `DataComponent` is a generated byte sized enum that a stack's patch is keyed by. It ends with
//! [`DataComponent::PLUGIN_SLOT_COUNT`] reserved variants (`PluginComponent0`, ...) whose ids follow
//! the vanilla ones: the component type a plugin registers as the n-th gets the id
//! `DataComponent::VANILLA_COUNT + n`, which is what a modded client's registry sync announces, and
//! the variant of that slot is what its values are stored under. Everything that moves stacks around
//! (clones, inventories, packets) therefore keeps them without knowing about plugins.
//!
//! The value of a plugin component is kept as the bytes of its network encoding
//! ([`PluginComponentImpl`]). A component in a stack is not length prefixed on the wire in most
//! places, so the server cannot skip a value it does not understand. Each type is registered with a
//! [`ComponentCodec`], a small declarative description of the encoding (varints, strings, nested
//! lists, ...) that is enough to find the end of a value. Where a stack is length prefixed (stacks
//! sent by clients) the bytes are taken as they are and only checked against the codec.
//!
//! A persistent type is saved with the stack under its full key as an NBT byte array holding the
//! network bytes. A type that is not registered when a stack is loaded is skipped.
//!
//! The registry is append only and closes before players can connect, like the item registry.

use std::any::Any;
use std::sync::{LazyLock, PoisonError, RwLock};

use pumpkin_nbt::tag::NbtTag;

use crate::data_component::DataComponent;
use crate::data_component_impl::DataComponentImpl;
use crate::plugin_registry::{PluginRegistry, RegistryError};

/// Largest value of one plugin component, in bytes of its network encoding.
pub const MAX_PLUGIN_COMPONENT_SIZE: usize = 262_144;
/// Deepest nesting of a codec.
pub const MAX_CODEC_DEPTH: usize = 16;
/// Largest number of nodes of a codec.
pub const MAX_CODEC_NODES: usize = 256;

/// The shape of the network encoding of a component value. Lists and sequences nest.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ComponentCodec {
    /// A `VarInt`.
    VarInt,
    /// A `VarLong`.
    VarLong,
    /// One byte, `0` or `1`.
    Bool,
    /// One byte.
    Byte,
    /// Two bytes, big endian.
    Short,
    /// Four bytes, big endian.
    Int,
    /// Eight bytes, big endian.
    Long,
    /// Four bytes, big endian IEEE 754.
    Float,
    /// Eight bytes, big endian IEEE 754.
    Double,
    /// A `VarInt` length and that many bytes of UTF-8. Identifiers are strings too.
    String,
    /// A `VarInt` length and that many bytes.
    ByteArray,
    /// 16 bytes.
    Uuid,
    /// A fixed number of bytes.
    FixedBytes(u32),
    /// A network NBT tag (an unnamed root).
    Nbt,
    /// An item stack in the play encoding.
    ItemStack,
    /// A data component patch: `VarInt` added, `VarInt` removed, then the added `(VarInt id,
    /// value)` pairs and the removed `VarInt` ids. Values of plugin components inside it are
    /// found with their own codec.
    ComponentPatch,
    /// A `bool` and, if it is true, the value.
    Optional(Box<ComponentCodec>),
    /// A `VarInt` count and that many values.
    List(Box<ComponentCodec>),
    /// The fields in order.
    Sequence(Vec<ComponentCodec>),
}

impl ComponentCodec {
    /// Checks the depth and the size of a codec.
    pub fn validate(&self) -> Result<(), RegistryError> {
        fn walk(
            codec: &ComponentCodec,
            depth: usize,
            nodes: &mut usize,
        ) -> Result<(), RegistryError> {
            *nodes += 1;
            if *nodes > MAX_CODEC_NODES {
                return Err(RegistryError::InvalidDefinition(format!(
                    "a codec has at most {MAX_CODEC_NODES} nodes"
                )));
            }
            if depth > MAX_CODEC_DEPTH {
                return Err(RegistryError::InvalidDefinition(format!(
                    "a codec nests at most {MAX_CODEC_DEPTH} levels"
                )));
            }
            match codec {
                ComponentCodec::Optional(inner) | ComponentCodec::List(inner) => {
                    walk(inner, depth + 1, nodes)
                }
                ComponentCodec::Sequence(fields) => {
                    for field in fields {
                        walk(field, depth + 1, nodes)?;
                    }
                    Ok(())
                }
                _ => Ok(()),
            }
        }
        walk(self, 0, &mut 0)
    }
}

/// A component type that a plugin registered.
pub struct PluginComponentType {
    /// The full resource location, `namespace:path`.
    pub key: &'static str,
    /// The slot of the type. Its id is [`DataComponent::to_id`].
    pub component: DataComponent,
    /// Whether the component is saved with the stack. A type that is not persistent is lost when
    /// the stack is saved and loaded, but still travels to clients.
    pub persistent: bool,
    /// How the value is encoded on the wire.
    pub codec: ComponentCodec,
}

impl PluginComponentType {
    /// The network id of the type.
    #[must_use]
    pub const fn id(&self) -> u8 {
        self.component.to_id()
    }
}

static REGISTRY: LazyLock<RwLock<PluginRegistry<PluginComponentType>>> = LazyLock::new(|| {
    RwLock::new(PluginRegistry::new(usize::from(
        DataComponent::PLUGIN_SLOT_COUNT,
    )))
});

fn read_registry() -> std::sync::RwLockReadGuard<'static, PluginRegistry<PluginComponentType>> {
    REGISTRY.read().unwrap_or_else(PoisonError::into_inner)
}

fn write_registry() -> std::sync::RwLockWriteGuard<'static, PluginRegistry<PluginComponentType>> {
    REGISTRY.write().unwrap_or_else(PoisonError::into_inner)
}

/// Registers a component type. Registering the same definition again returns the existing type, a
/// different one for a known key is [`RegistryError::Duplicate`].
pub fn register_plugin_component_type(
    key: &str,
    persistent: bool,
    codec: ComponentCodec,
) -> Result<&'static PluginComponentType, RegistryError> {
    codec.validate()?;
    let same = {
        let codec = codec.clone();
        move |existing: &'static PluginComponentType| {
            existing.persistent == persistent && existing.codec == codec
        }
    };
    write_registry().register(key, same, |index, key| PluginComponentType {
        key,
        // The registry holds at most PLUGIN_SLOT_COUNT entries, so the slot exists. The fallback is
        // never taken, it only keeps this free of panics.
        component: u8::try_from(index)
            .ok()
            .and_then(DataComponent::from_plugin_slot)
            .unwrap_or(DataComponent::CustomData),
        persistent,
        codec,
    })
}

/// Closes the registry. Later registrations fail with [`RegistryError::Frozen`].
pub fn freeze_plugin_component_types() {
    write_registry().freeze();
}

#[must_use]
pub fn is_plugin_component_registry_frozen() -> bool {
    read_registry().is_frozen()
}

/// The registered component types in id order.
#[must_use]
pub fn plugin_component_types() -> Vec<&'static PluginComponentType> {
    read_registry().entries().to_vec()
}

#[must_use]
pub fn plugin_component_type_by_key(key: &str) -> Option<&'static PluginComponentType> {
    read_registry().get_by_key(key)
}

impl DataComponent {
    /// The plugin component type of this slot. `None` for a vanilla component and for a slot no
    /// plugin registered a type for.
    #[must_use]
    pub fn plugin_type(self) -> Option<&'static PluginComponentType> {
        let slot = self.plugin_slot()?;
        read_registry().get_by_index(usize::from(slot))
    }

    /// The slot of a plugin component type by its full key.
    #[must_use]
    pub fn from_plugin_key(key: &str) -> Option<Self> {
        plugin_component_type_by_key(key).map(|component_type| component_type.component)
    }
}

/// The value of a plugin component: the bytes of its network encoding.
#[derive(Clone, PartialEq, Eq)]
pub struct PluginComponentImpl {
    /// The slot of the type, see [`PluginComponentType::component`].
    pub component: DataComponent,
    pub data: Vec<u8>,
}

impl PluginComponentImpl {
    #[must_use]
    pub const fn new(component: DataComponent, data: Vec<u8>) -> Self {
        Self { component, data }
    }

    /// Reads a value saved by [`DataComponentImpl::write_data`].
    #[must_use]
    pub fn read_data(component: DataComponent, tag: &NbtTag) -> Option<Self> {
        let NbtTag::ByteArray(bytes) = tag else {
            return None;
        };
        if bytes.len() > MAX_PLUGIN_COMPONENT_SIZE {
            return None;
        }
        Some(Self {
            component,
            data: bytes.iter().map(|byte| *byte as u8).collect(),
        })
    }
}

impl DataComponentImpl for PluginComponentImpl {
    fn write_data(&self) -> NbtTag {
        NbtTag::ByteArray(self.data.iter().map(|byte| *byte as i8).collect())
    }

    fn equal(&self, other: &dyn DataComponentImpl) -> bool {
        other
            .as_any()
            .downcast_ref::<Self>()
            .is_some_and(|other| self == other)
    }

    /// Not meaningful for a value that can be any slot, use [`DataComponentImpl::get_self_enum`].
    fn get_enum() -> DataComponent
    where
        Self: Sized,
    {
        DataComponent::CustomData
    }

    fn get_self_enum(&self) -> DataComponent {
        self.component
    }

    fn to_dyn(self) -> Box<dyn DataComponentImpl> {
        Box::new(self)
    }

    fn clone_dyn(&self) -> Box<dyn DataComponentImpl> {
        Box::new(self.clone())
    }

    fn as_any(&self) -> &dyn Any {
        self
    }

    fn as_mut_any(&mut self) -> &mut dyn Any {
        self
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn slots_follow_the_vanilla_ids() {
        assert_eq!(DataComponent::VANILLA_COUNT, 122);
        assert_eq!(
            DataComponent::from_plugin_slot(0).map(DataComponent::to_id),
            Some(DataComponent::VANILLA_COUNT)
        );
        assert_eq!(DataComponent::CustomData.plugin_slot(), None);
        assert_eq!(DataComponent::PluginComponent5.plugin_slot(), Some(5));
        assert!(DataComponent::from_plugin_slot(DataComponent::PLUGIN_SLOT_COUNT).is_none());
    }

    #[test]
    fn registered_type_round_trips_through_nbt() {
        let component_type = register_plugin_component_type(
            "test_components:computer_id",
            true,
            ComponentCodec::VarInt,
        )
        .unwrap();
        assert!(component_type.component.plugin_slot().is_some());
        assert_eq!(
            component_type.component.plugin_type().map(|t| t.key),
            Some("test_components:computer_id")
        );

        let value = PluginComponentImpl::new(component_type.component, vec![1, 2, 255]);
        let tag = value.write_data();
        let read = PluginComponentImpl::read_data(component_type.component, &tag).unwrap();
        assert!(read == value);
        assert!(value.equal(&read));
        assert!(
            register_plugin_component_type(
                "test_components:computer_id",
                false,
                ComponentCodec::VarInt
            )
            .is_err()
        );
    }
}
